    "There is already an account with this email.": ["Er is al een account met dit e-mailadres.", "Es gibt schon ein Konto mit dieser E-Mail.", "Un compte existe déjà avec cet e-mail.", "Ya existe una cuenta con este correo.", "Já existe uma conta com este e-mail."],
    "Choose a password of at least 6 characters.": ["Kies een wachtwoord van minstens 6 tekens.", "Wähle ein Passwort mit mindestens 6 Zeichen.", "Choisissez un mot de passe d'au moins 6 caractères.", "Elige una contraseña de al menos 6 caracteres.", "Escolha uma palavra-passe com pelo menos 6 caracteres."],
    "This email address is not valid.": ["Dit e-mailadres is niet geldig.", "Diese E-Mail-Adresse ist ungültig.", "Cette adresse e-mail n'est pas valide.", "Este correo no es válido.", "Este e-mail não é válido."],
    "Something went wrong. Please try again.": ["Er ging iets mis. Probeer het opnieuw.", "Etwas ist schiefgelaufen. Bitte versuche es noch einmal.", "Un problème est survenu. Réessayez.", "Algo salió mal. Inténtalo de nuevo.", "Algo correu mal. Tente de novo."],
    "Grown-ups: please solve the sum to create an account.": ["Volwassenen: los de som op om een account te maken.", "Erwachsene: Bitte die Rechenaufgabe lösen, um ein Konto zu erstellen.", "Adultes : résolvez le calcul pour créer un compte.", "Adultos: resolved la suma para crear una cuenta.", "Adultos: resolvam a conta para criar uma conta."],
    "That is not right. Please ask a grown-up.": ["Dat klopt niet. Vraag het aan een volwassene.", "Das stimmt nicht. Bitte frag einen Erwachsenen.", "Ce n'est pas ça. Demande à un adulte.", "No es correcto. Pide ayuda a un adulto.", "Não está certo. Pede ajuda a um adulto."],
    "Account created!": ["Account gemaakt!", "Konto erstellt!", "Compte créé !", "¡Cuenta creada!", "Conta criada!"],
    "Enter your email first.": ["Vul eerst je e-mailadres in.", "Gib zuerst deine E-Mail ein.", "Saisissez d'abord votre e-mail.", "Escribe primero tu correo.", "Escreva primeiro o seu e-mail."],
    "We sent an email to reset your password.": ["We hebben een e-mail gestuurd om je wachtwoord te herstellen.", "Wir haben eine E-Mail zum Zurücksetzen des Passworts geschickt.", "Un e-mail de réinitialisation a été envoyé.", "Hemos enviado un correo para restablecer la contraseña.", "Enviámos um e-mail para repor a palavra-passe."],
    "Which progress do you want to keep?": ["Welke voortgang wil je bewaren?", "Welchen Fortschritt möchtest du behalten?", "Quelle progression veux-tu garder ?", "¿Qué progreso quieres conservar?", "Que progresso queres manter?"],
